ST.xhtml:p:
IF bFirstRun THEN
    rOutput := rInput;
    bFirstRun := FALSE;
ELSE
    IF ABS(rInput - rOutput) > rMaxDiff THEN
        rOutput := rOutput; // 超出限幅，保持上次值不变
    ELSE
        rOutput := rInput;  // 正常范围内，更新
    END_IF;
END_IF;

IF bFirstRun THEN
    rOutput := rInput;
    bFirstRun := FALSE;
ELSE
    rOutput := rOutput + rAlpha * (rInput - rOutput);
END_IF;

// 存入循环缓冲区
aBuffer[iPtr] := rInput;
iPtr := iPtr + 1;
IF iPtr > 3 THEN iPtr := 1; END_IF;

// 复制到排序数组
aSort := aBuffer;

// 冒泡排序 (3个元素，最多3次比较)
FOR i := 1 TO 2 DO
    FOR j := 1 TO (3 - i) DO
        IF aSort[j] > aSort[j+1] THEN
            rTemp := aSort[j];
            aSort[j] := aSort[j+1];
            aSort[j+1] := rTemp;
        END_IF;
    END_FOR;
END_FOR;

// 取中间值
rOutput := aSort[2];

IF uiSize > 100 THEN uiSize := 100; END_IF;
IF uiSize = 0 THEN uiSize := 1; END_IF;

// 更新缓冲区
aBuffer[iPtr] := rInput;
iPtr := iPtr + 1;
IF iPtr > uiSize THEN iPtr := 1; END_IF;

// 求和计算平均值
rSum := 0.0;
FOR i := 1 TO uiSize DO
    rSum := rSum + aBuffer[i];
END_FOR;

rOutput := rSum / UINT_TO_REAL(uiSize);

// --- 主逻辑 ---

// 1. 物理量转换
IF (stConfig.rMaxVoltage - stConfig.rZeroVoltage) <= 0.0 THEN
    bAlarm := TRUE;
    rRawValue := 0.0;
ELSE
    bAlarm := FALSE;
    rRawValue := (UINT_TO_REAL(uiRawADC) - stConfig.rZeroVoltage) / 
                 (stConfig.rMaxVoltage - stConfig.rZeroVoltage) * 
                 stConfig.rRange;
    rRawValue := LIMIT(0.0,rRawValue,stConfig.rRange);
END_IF;

// 2. 滤波处理链 (采用单一配置切换，若需组合可级联调用)
CASE stFilterCfg.eType OF
    FTLowPass:
        fbLowPass(rInput := rRawValue, rAlpha := stFilterCfg.rParam1);
        rActualValue := fbLowPass.rOutput;

    FTLimit:
        fbLimit(rInput := rRawValue, rMaxDiff := stFilterCfg.rParam1);
        rActualValue := fbLimit.rOutput;

    FTMedian:
        fbMedian(rInput := rRawValue);
        rActualValue := fbMedian.rOutput;

    FTMovingAverage:
        fbMovingAvg(rInput := rRawValue, uiSize := stFilterCfg.uiParam2);
        rActualValue := fbMovingAvg.rOutput;

    FTLowPassAndMovingAverage:
        fbLowPass(rInput := rRawValue, rAlpha := stFilterCfg.rParam1);
        fbMovingAvg(rInput :=  fbLowPass.rOutput, uiSize := stFilterCfg.uiParam2);
        rActualValue := fbMovingAvg.rOutput;     

ELSE
    // None: 不滤波
    rActualValue := rRawValue;
END_CASE;

rActualValueDeriv := ( rActualValue - rLastActualValue )/cTCycle;
rLastActualValue := rActualValue;

