stConfig.rZeroVoltage := rZero;
stConfig.rMaxVoltage  := rMax;
stConfig.rRange       := rRng;
Init := TRUE;

stFilterCfg.eType := eType;
stFilterCfg.rParam1 := rParam1;
stFilterCfg.uiParam2 := uiParam2;
SetFilter := TRUE;

