ST.xhtml:xhtml:
stConfig.rZeroVoltage := rZero;
stConfig.rMaxVoltage  := rMax;
stConfig.rRange       := rRng;
Init := TRUE;

stFilterCfg.eType := eType;
stFilterCfg.rParam1 := rParam1;
stFilterCfg.uiParam2 := uiParam2;
SetFilter := TRUE;

ST.xhtml:p:
(*=====================================================================*)
(*               1. 运算与条件准备 (每周期执行)                          *)
(*=====================================================================*)

// 速度与压力设定值计算 (仅在初始化完成后计算)
IF iState >= STATE_IDLE THEN

    MaxVel  := UINT_TO_LREAL(uiMaxMotorSpeed) * (360.0/60.0); 
    MaxAcc  := 2.0 * MaxVel;
    MaxJerk := 3.0 * MaxVel;
    fMotorSpeedLimit := UINT_TO_LREAL(uiMaxMotorSpeed) * LIMIT(0, FlowRateLimit, 1000) * 0.001;
    fSetVel := REAL_TO_LREAL(SetVelCmd);
    fSetVel := LIMIT( dfMinVel, fSetVel, fMotorSpeedLimit );     

    fSetVel := fSetVel * dir;
END_IF;

// 使能命令统一映射 (PowerEnable 掌控全局)
bPowerCmd := StartMotor AND (iState >= STATE_IDLE);

(*=====================================================================*)
(*               2. 状态机 (仅控制逻辑流转与指令赋值)                     *)
(*=====================================================================*)

CASE iState OF

    0: // 0: 初始化IP与SDO1

        fbSDORead( Axis := nAxisRef, Execute := TRUE, Index := 19, Size := 1 );
        iState := STATE_READ_SDO1;

    1: // 1: 等待SDO1读取完成 (异步处理)
        fbSDORead( Axis := nAxisRef, Execute := TRUE, Index := 19, Size := 1 );
        IF fbSDORead.Done THEN
            wNumBitEnc := WORD_TO_UDINT( fbSDORead.ValueArray[1] );
            IF wNumBitEnc > 1 AND wNumBitEnc < 60 THEN
                wTempVar := SHL(1, wNumBitEnc);
            ELSE
                wTempVar := SHL(1, 12);
            END_IF;
            dfResolutionEnc := UDINT_TO_LREAL(wTempVar);
            fbSDORead( Execute := FALSE );
            fbSDORead( Axis := nAxisRef, Execute := TRUE, Index := 106, Size := 1 );
            iState := STATE_READ_SDO2;
        END_IF;

    2: // 2: 等待SDO2读取完成
        fbSDORead( Axis := nAxisRef, Execute := TRUE, Index := 106, Size := 1 );
        IF fbSDORead.Done THEN
            wDirRotate := fbSDORead.ValueArray[1];
            fbSDORead( Execute := FALSE );
            iState := STATE_WRITE_PARAM;
        END_IF;

    10: // 10: 写入参数与仿真设置
        fbSetPar(Axis := nAxisRef, Execute := TRUE, ParameterNumber:= 1003, Value := dfResolutionEnc);  // 4096
        fbSetBoolPar(Axis := nAxisRef, Execute := TRUE, ParameterNumber:= 1000, Value := EnSimulation);
        IF fbSetPar.Done AND fbSetBoolPar.Done THEN
            fbSetPar(Execute := FALSE);
            fbSetBoolPar(Execute := FALSE);
            fbReset( Axis := nAxisRef, Execute := FALSE );
            fbStartMotorSelfLearn( Axis := nAxisRef, Execute := FALSE );
            iState := STATE_SELFLEARN;
        END_IF;

    20: // 20: 自学习
        IF SelfLearn THEN
            fbStartMotorSelfLearn( Axis := nAxisRef, Execute := TRUE,
                                   ResetServoParam := TRUE, WriteServoParam := TRUE,
                                   MotorLearn := TRUE, ParameterArray := arMotorParam );
            IF fbStartMotorSelfLearn.Done THEN
                fbStartMotorSelfLearn(Execute := FALSE);
                iState := STATE_SET_MODE;
            END_IF;
        ELSE
            iState := STATE_SET_MODE;
        END_IF;

    30: // 30: 设置控制模式
        fbModeCtrl(Axis := nAxisRef, Execute := TRUE, ControllerMode := mcFollowVelocity, ExecutionMode := mcImmediately);
        IF fbModeCtrl.Done THEN
            fbModeCtrl(Execute := FALSE);
            iState := STATE_IDLE;
        END_IF;

    40: // 40: 待机状态 (等待 PowerEnable)
        bMoveCmd := FALSE;
        dfSetVel := 0.0;
        // 核心逻辑：给使能 且 电机已成功使能，则立即启动速度控制
        IF StartMotor AND fbPower.Status THEN
            iState := STATE_RUNNING;
        END_IF;

    50: // 50: 速度运行中
        bMoveCmd := TRUE;
        dfSetVel := fSetVel * (360.0/60.0); // RPM 转换 UU/s

        // 核心逻辑：一旦失去使能信号，立即进入减速停机
        IF NOT StartMotor THEN
            iState := STATE_STOPPING;
        END_IF;

    60: // 60: 减速停机中
        bMoveCmd := TRUE;  // 保持速度块 Execute，以控制减速曲线
        dfSetVel := 0.0;   // 目标速度设为 0

        // 减速中途，如果使能信号恢复，立即恢复运行
        IF StartMotor THEN
            fbDelay(IN := FALSE); // 清除停机定时器
            iState := STATE_RUNNING;
        ELSE
            // 速度低于阈值开始计时，若速度反弹则自动复位定时器
            fbDelay(IN := ABS(dfActVel) < 5.0, PT := TIME#1S);
            IF fbDelay.Q THEN
                bMoveCmd := FALSE;    // 停机完成，撤销速度控制命令
                fbDelay(IN := FALSE); // 复位定时器
                iState := STATE_IDLE; // 回到待机 (bPowerCmd随之变FALSE，自动断使能)
            END_IF;
        END_IF;

    99: // 99: 错误状态
        Error := TRUE;
        bMoveCmd := FALSE;

END_CASE;

(*=====================================================================*)
(*          3. 统一调用 PLCopen 功能块 (严格遵循规范，每周期执行)         *)
(*=====================================================================*)
//(*  更新液压系统模型 *)
//hydraulic_sys.motorvelocity := SetVelCmd;
//hydraulic_sys.tcycle := tcycle;
//hydraulic_sys.knum := 5.4;   // 4.2, 1.162, 5.4
//hydraulic_sys.ttau := 1.0;   // 0.4, 0.171, 1.0 
//hydraulic_sys.delaytime := 0.0;  // 1.0 max , 0.438
//hydraulic_sys();

// 使能控制
fbPower( Axis := nAxisRef, Enable := bPowerCmd, EnablePositive := TRUE, EnableNegative := TRUE);

// 速度跟随控制
fbFollowVel( Axis := nAxisRef, Execute := bMoveCmd, Velocity := dfSetVel);

// 反馈读取 (进入Idle后即开始读取，保证状态监控连续性)
IF iState >= STATE_IDLE THEN
    fbReadVel( Axis := nAxisRef, Enable := TRUE, Velocity => dfActVel, VelocityFeedback => dfActVelFb);
    fbReadPos( Axis := nAxisRef, Enable := TRUE, Position => dfActPosFb );
    fbReadTor( Axis := nAxisRef, Enable := TRUE, Torque   => dfActTor);  
END_IF;

// 错误捕获 (从运动功能块中提取错误)
IF fbFollowVel.Error THEN
    ErrorID := fbFollowVel.ErrorID;
    iState := STATE_ERROR;
END_IF;

(*=====================================================================*)
(*                      4. 输出映射                                     *)
(*=====================================================================*)

Status          := DINT_TO_UINT(iState);
outErrorID      := ErrorID;
ActSpeedRPM := DINT_TO_UINT( LREAL_TO_DINT(dfActVel*60.0/360.0) );
ActTorquePercent := DINT_TO_UINT( LREAL_TO_DINT(dfActTor) );

// 仅作监视调试使用
// 轴：启动信号、停止信号、设定位置、设定速度、设定结束速度、设定压力
stHydAxisRef.bStart := bStart;
stHydAxisRef.bStop := bStop;
stHydAxisRef.uiDir := uiDir;
stHydAxisRef.udiPos := udiPos;
stHydAxisRef.uiSpd := uiSpd;
stHydAxisRef.uiEndSpd := uiEndSpd;
stHydAxisRef.uiPres := uiPres;

//--- 1. 边沿检测 & 参数映射 ---
rTrigStart(CLK := bStart);
rTrigStop(CLK := bStop);
rTrigEStop(CLK := bEStop);
rTrigReset(CLK := bReset);
// 将Done检测移出CASE，确保全周期扫描，不错过InEndVelocity的上升沿
rTrigDone(CLK := fbMoveContAbs.InEndVelocity); 

rMaxSpeed := stHydAxisRef.rMaxSpeed;

//IF stHydAxisRef.rCylinderExtendArea > 0.0 AND stHydAxisRef.rCylinderRetractArea > 0.0 THEN
//  IF uiDir = 1 THEN
//    rMaxSpeed := stHydAxisRef.rMaxSpeedExtend;
//  ELSE
//    rMaxSpeed := stHydAxisRef.rMaxSpeedRetract;
//  END_IF;
//END_IF;

rPres := MAX(UINT_TO_REAL(uiPres), 0.0)*0.1;   //压力设定
rVel  := UINT_TO_REAL(uiSpd)*0.1*0.01*rMaxSpeed;  //速度设定
rEndVel := UINT_TO_REAL(uiEndSpd)*0.1*0.01*rMaxSpeed;  //终点速度，连续轨迹关键：设定终点速度等于最大速度，实现"到位不停车"或平滑过渡
rPos  := UDINT_TO_REAL(udiPos)*0.01;  //位置设定


IF uiAcc = 0 THEN rAcc := 200; ELSE rAcc  := rMaxSpeed/UINT_TO_REAL(uiAcc)*1000; END_IF;  
IF uiDec = 0 THEN rDec := 200; ELSE rDec  := rMaxSpeed/UINT_TO_REAL(uiDec)*1000; END_IF;  
IF uiJerk = 0 THEN rJerk := 0; ELSE rJerk := rMaxSpeed/UINT_TO_REAL(uiJerk); END_IF;

iDir := uiDir;  
//--- 2. 状态机主逻辑 ---
CASE iStep OF

    0: // 初始化
        fbCreate(USE_SIMULATION := 0, MECHANISM_TYPE:= stHydAxisRef.iMechanismType);
        IF fbCreate.DONE THEN
            siAxisId := fbCreate.AXISID;
            stHydAxisRef.iAxisID := siAxisId;
            SetVelocityToFlowGain(stHydAxisRef.rVelToFlowGain);
            SetPidType( SINT_TO_REAL(stHydAxisRef.iTypePressurePID) );
            SetCylinderConfig(stHydAxisRef.rCylinderExtendArea, stHydAxisRef.rCylinderRetractArea );
            fbCalcMaxSpeed(stHydAxisRef.rCylinderExtendArea, stHydAxisRef.rCylinderRetractArea, 1800, 50, stHydAxisRef.iMechanismType );
            stHydAxisRef.rMaxSpeedExtend  := fbCalcMaxSpeed.rMaxSpeedExtend;
            stHydAxisRef.rMaxSpeedRetract := fbCalcMaxSpeed.rMaxSpeedRetract;
            iStep := 10;
        ELSIF fbCreate.ERROR THEN
            bAlarm := TRUE; dwAlarmID := 16#00000001; iStep := 900;
        END_IF;

    10: // 空闲
        bCmdExecute := FALSE; 
        bDone := FALSE; // 重置完成信号
        IF rTrigEStop.Q THEN
            iStep := 300;
        ELSIF rTrigStop.Q THEN
            iStep := 200;
        ELSIF rTrigReset.Q AND bAlarm THEN
            iStep := 400;
        ELSIF rTrigStart.Q AND uiMode >= 1 AND uiMode <= 3 THEN
            uiActiveMode := uiMode; 
            bCmdExecute := TRUE; // 启动时直接置高
            iStep := 100;           
        END_IF;

    100: // 运行中
        // 默认保持执行状态
        bCmdExecute := TRUE; 

        // 1. 错误监测 (所有模式通用)
        CASE uiActiveMode OF
            1: bFBError := fbMoveContAbs.ERROR; wFBErrorID := fbMoveContAbs.ERRORID;
            2: bFBError := fbMoveVel.ERROR; wFBErrorID := fbMoveVel.ERRORID;
            3: bFBError := fbPresHdl.ERROR; wFBErrorID := fbPresHdl.ERRORID;
        END_CASE;

        IF bFBError THEN
            bAlarm := TRUE; dwAlarmID := wFBErrorID; iStep := 900;

        // 2. 段切换触发 (核心逻辑)
        ELSIF rTrigStart.Q THEN
            // 检测到新的启动信号
            IF uiMode = uiActiveMode THEN
                // 同模式重触发（例如射胶第一段->第二段）：
                // 进入过渡步，拉低Execute，下一周期再拉高，产生上升沿
                iStep := 105; 
            ELSIF uiMode >= 1 AND uiMode <= 3 THEN
                // 跨模式切换（如位置->压力）：直接更改模式
                // 注意：有些运动控制库需要Stop才能切换模式，这里假设支持无缝切换或由BufferMode处理
                uiActiveMode := uiMode; 
                // 如果库不支持直接修改参数切换，此处也应跳转Step 105
            END_IF;
        END_IF;

        // 3. 中断监测
        IF rTrigEStop.Q THEN iStep := 300;
        ELSIF rTrigStop.Q THEN iStep := 200;
        END_IF;

    105: // 运行过渡步 (产生Execute脉冲)
        // 此步仅保持1个周期
        bCmdExecute := FALSE; // 拉低Execute
        bDone := FALSE;      // 清除上一段的完成标志
        iStep := 100;        // 立即回100，在100中bCmdExecute变TRUE，形成上升沿

    200: // 正常停止
        fbStop(AXISID := siAxisId, EXECUTE := TRUE, DECELERATION := rDec); // 这里的Execute通常需要脉冲或持续，视具体FB而定，假设持续
        IF fbStop.DONE THEN
            fbStop(EXECUTE := FALSE); // 停止命令需复位
            iStep := 10;
        ELSIF fbStop.ERROR THEN
            bAlarm := TRUE; dwAlarmID := fbStop.ERRORID; iStep := 900;
        END_IF;

    300: // 急停
        fbEStop(AXISID := siAxisId, EXECUTE := TRUE, DECELERATION := 99999.0);
        IF fbEStop.DONE OR fbEStop.ERROR THEN
            fbEStop(EXECUTE := FALSE);
            bAlarm := TRUE; dwAlarmID := 16#0000FFFF; iStep := 900;
        END_IF;

    400: // 报警复位
        fbReset(AXISID := siAxisId, EXECUTE := TRUE);
        IF fbReset.DONE THEN
            fbReset(EXECUTE := FALSE);
            bAlarm := FALSE; dwAlarmID := 0; iStep := 10;
        ELSIF fbReset.ERROR THEN
            bAlarm := TRUE; dwAlarmID := fbReset.ERRORID; iStep := 900;
        END_IF;

    900: // 报警等待
        IF rTrigReset.Q THEN
            iStep := 400;
        END_IF;

END_CASE;

//--- 3. 底层 FB 统一调用区 ---
// 注意：fbStop, fbEStop, fbReset的调用已在State中处理或者在这里根据iStep统一处理
// 为了代码清晰，建议持续调用，EXECUTE由状态控制
// 但为了符合原代码结构，下面保留原风格，修正MoveContinuousAbsolute的参数

// Create 只在Init或Reset时调用一次即可，原代码持续调用没问题(内部有Enable管理)
// fbCreate(...); 
rCycle := rCycle + 0.001;
fbHYD_SetAxisFeedback(
     AXISID := siAxisId,
     ENABLE := 1,
     ACT_POSITION := stHydAxisRef.rActPosition,
     ACT_VELOCITY := stHydAxisRef.rVeloctity,
     ACT_FLOW := 0,
     ACT_PRESSURE := stHydAxisRef.rActPressure,
     TIMESTAMP := rCycle
   );

fbMoveContAbs(
    AXISID := siAxisId, 
    EXECUTE := (uiActiveMode = 1) AND bCmdExecute, 
    POSITION := rPos, 
    VELOCITY := rVel,
    ENDVELOCITY := rEndVel,    // 关键修改：设定终点速度，保证InEndVelocity能正常触发
    ENDVELOCITYDIRECTION := iDir, // 0=Current/Positive, 需根据实际情况设定
    ACCELERATION := rAcc, 
    DECELERATION := rDec, 
    JERK := rJerk, 
    DIRECTION := iDir,
    ADAPTENDVELTOAVOIDOVERSHOOT := TRUE,
    PRESSURELIMIT := rPres
    // BufferMode 可根据库支持情况添加，若不支持则依靠Step 105的脉冲机制
);



fbMoveVel(
    AXISID := siAxisId, EXECUTE := (uiActiveMode = 2) AND bCmdExecute, 
    CONTINUOUSUPDATE := TRUE, VELOCITY := rVel,
    ACCELERATION := rAcc, DECELERATION := rDec, JERK := rJerk, DIRECTION := iDir, BUFFERMODE := 0,PRESSURELIMIT := rPres);

fbPresHdl(
    AXISID := siAxisId, EXECUTE := (uiActiveMode = 3) AND bCmdExecute, 
    CONTINUOUSUPDATE := TRUE, PRESSURE := rPres, PRESSURERAMPRATE := rAcc, DURATION := 0.0, BUFFERMODE := 0);

// Stop/EStop/Reset 需要特殊处理Execute信号，防止一直给TRUE
// 修改为根据状态决定EXECUTE
IF iStep = 200 THEN
    fbStop(AXISID := siAxisId, EXECUTE := TRUE, DECELERATION := rDec);
ELSE
    fbStop(AXISID := siAxisId, EXECUTE := FALSE, DECELERATION := rDec);
END_IF;

IF iStep = 300 THEN
    fbEStop(AXISID := siAxisId, EXECUTE := TRUE, DECELERATION := 99999.0);
ELSE
    fbEStop(AXISID := siAxisId, EXECUTE := FALSE, DECELERATION := 99999.0);
END_IF;

IF iStep = 400 THEN
    fbReset(AXISID := siAxisId, EXECUTE := TRUE);
ELSE
    fbReset(AXISID := siAxisId, EXECUTE := FALSE);
END_IF;

// 仅作监视调试使用
// 轴：反馈位置、反馈速度、反馈流量、反馈压力、反馈当前步号
fbReadFB(AXISID := siAxisId, ENABLE := TRUE);
IF fbReadFB.VALID THEN
    stHydAxisRef.rPosition  := fbReadFB.POSITION;
    stHydAxisRef.rVeloctity := fbReadFB.VELOCITY;
    stHydAxisRef.rFlow      := fbReadFB.FLOW;
    stHydAxisRef.rPerssure  := fbReadFB.PRESSURE;
END_IF;
//引出iStep状态
stHydAxisRef.iStep := iStep;
//--- 4. 状态输出汇总 ---
IF iStep = 10 THEN
    bBusy := FALSE; 
    bDone := FALSE; // 空闲状态下没有完成信号
ELSIF iStep = 100 OR iStep = 105 THEN
    bBusy := TRUE;  // 忙

    // 区分模式的Done信号
    IF uiActiveMode = 1 THEN
        // 位置模式：InEndVelocity TRUE 表示当前段已到达且速度吻合，可以进行下一段
        bDone := fbMoveContAbs.InEndVelocity; 
    ELSIF uiActiveMode = 2 THEN
        // 速度模式：通常持续运行，除非有特定停止条件，这里暂不输出Done，或根据是否达到速度判定
        bDone := fbMoveVel.InVelocity; 
    ELSIF uiActiveMode = 3 THEN
        // 压力模式
        bDone := fbPresHdl.INPRESSURE;
    ELSE
        bDone := FALSE;
    END_IF;

    bInVelocity := fbMoveVel.InVelocity;
    bInPressure := fbPresHdl.INPRESSURE;

ELSIF iStep = 200 THEN
    bBusy := TRUE; bDone := FALSE;
ELSIF iStep = 300 THEN
    bBusy := TRUE; bDone := FALSE;
ELSIF iStep = 400 THEN  
    bBusy := TRUE; bDone := FALSE;
ELSE // 900 等
    bBusy := FALSE; bDone := FALSE;
END_IF;

//TraceVariable( INDEX := 0,   VALUE := rPosition );
//TraceVariable( INDEX := 1,   VALUE := rVeloctity );

