                      PARAMETERNUMBER := iCylinderRetractArea, VALUE := REAL_TO_LREAL(rRetractArea) );


SetCylinderConfig := fbHYD_WriteParameter.Done;

ST.xhtml:p:
(* Application smoke example. No pump request or servo arbitration is visible here. *)
IF NOT bInitialized THEN
    stHydAxisRef.iAxisID := -1;
    bMachineEnable := TRUE;
    bHydraulicRun := FALSE;
    bElectricRun := FALSE;
    rHydraulicVelocity := 20.0;
    rElectricVelocity := 1200.0;
    bInitialized := TRUE;
END_IF;

(* Both adapters expose the same common command names. *)
fbHydraulicAxis(
    stHydAxisRef := stHydAxisRef,
    bEnable := bMachineEnable,
    bMove := bHydraulicRun,
    rVelocity := rHydraulicVelocity,
    bStop := FALSE,
    bEStop := FALSE,
    bReset := FALSE,
    uiDir := 1,
    uiMode := 2,
    uiSpd := LREAL_TO_UINT(ABS(rHydraulicVelocity)),
    udiPos := 0);

fbElectricAxis(
    AxisRef := stElectricAxisRef,
    bEnable := bMachineEnable,
    bMove := bElectricRun,
    rVelocity := rElectricVelocity);

(* OOP registration boundary; concrete-to-interface assignment is handled by the target compiler. *)
iHydraulicAxis := fbHydraulicAxis;
iElectricAxis := fbElectricAxis;
fbTechnology(
    iHydraulicAxis := iHydraulicAxis,
    iElectricAxis := iElectricAxis,
    bEnable := bMachineEnable,
    ePumpPolicy := eMotionDefault,
    bAllowNegative := FALSE,
    uiMaxMotorSpeed := 1800,
    bRegisterHydraulicAxis := bInitialized,
    bRegisterElectricAxis := bInitialized,
    bClampExecute := bClampCommand,
    bInjectionExecute := bInjectionCommand);

// 1. 默认状态为无效
bValid := FALSE;

// 2. 参数有效性检查 (面积必须大于0，防止除零)
IF (rAreaExtendSide <= 0.0) OR (rAreaRetractSide <= 0.0) OR 
   (rPumpMaxRPM < 0.0) OR (rPumpDisplacement <= 0.0) THEN

    rMaxSpeedExtend  := 0.0;
    rMaxSpeedRetract := 0.0;

ELSE
    bValid := TRUE;

    // 3. 计算油泵最大流量
    // 结果单位为 cc/min (立方厘米/分)=mL/min
    rMaxFlowRate_cc := rPumpDisplacement * rPumpMaxRPM;

    // 4. 计算伸出最大速度
    // 公式: (流量 cc/min * 1000) / (面积 mm² * 60)
    // 简化为: 流量 * 16.667 / 面积
    rMaxSpeedExtend := (rMaxFlowRate_cc * rCoeff) / rAreaExtendSide;

    // 5. 计算缩回最大速度
    rMaxSpeedRetract := (rMaxFlowRate_cc * rCoeff) / rAreaRetractSide;

    IF iMechanismType = 1 THEN
      rMaxSpeedExtend  := rMaxSpeedExtend * rKVelocityRateExtend; // kv=f(Xm),变速比是动模板位置的函数
      rMaxSpeedRetract := rMaxSpeedRetract * rKVelocityRateRetract;
    END_IF;
END_IF;

IF bEStop THEN
    iState := 7;
ELSIF bReset THEN
    iState := 0;
ELSIF bEnable THEN
    iState := 2;
ELSE
    iState := 1;
END_IF;
bEnabled := bEnable AND NOT bEStop;
bBusy := FALSE;
bDone := FALSE;
bError := (iState = 99);

fbPower(Axis := AxisRef, Enable := bEnable, EnablePositive := TRUE, EnableNegative := TRUE);
fbFollowVelocity(Axis := AxisRef, Execute := bMove, Velocity := rVelocity);
bEnabled := fbPower.Status;
bBusy := fbFollowVelocity.Busy;
bDone := NOT fbFollowVelocity.Busy AND NOT fbFollowVelocity.Error AND bMove;
bError := fbPower.Error OR fbFollowVelocity.Error;
udiErrorID := WORD_TO_UDINT(fbFollowVelocity.ErrorID);
IF bError THEN
    eState := eError;
ELSIF bBusy THEN
    eState := eBusy;
ELSIF bEnabled THEN
    eState := eReady;
ELSE
    eState := eIdle;
END_IF;
stStatus.eState := eState;
stStatus.bEnabled := bEnabled;
stStatus.bBusy := bBusy;
stStatus.bDone := bDone;
stStatus.bError := bError;
stStatus.udiErrorID := udiErrorID;

fbLegacyHydAxis(
    stHydAxisRef := stHydAxisRef,
    bStart := bStart OR bEnable OR bMove,
    bStop := bStop,
    bEStop := bEStop,
    bReset := bReset,
    uiDir := uiDir,
    uiMode := SEL(bMove OR bEnable, 2, uiMode),
    uiPres := uiPres,
    uiSpd := SEL(bMove OR bEnable, LREAL_TO_UINT(ABS(rVelocity)), uiSpd),
    udiPos := udiPos);
fbReadStatus(AXISID := stHydAxisRef.iAxisID, ENABLE := TRUE);
bBusy := fbLegacyHydAxis.bBusy;
bDone := fbLegacyHydAxis.bDone;
bError := fbLegacyHydAxis.bAlarm OR fbReadStatus.ERROR;
bEnabled := (stHydAxisRef.iAxisID >= 0) AND NOT bError;
udiErrorID := DWORD_TO_UDINT(fbLegacyHydAxis.dwAlarmID);
rRequestedFlow := fbReadStatus.REQUESTEDFLOW;
bPumpConflict := fbReadStatus.PUMPSPEEDLIMITACTIVE OR fbReadStatus.FLOWLIMITACTIVE;
IF bError THEN
    eState := eError;
ELSIF bBusy THEN
    eState := eBusy;
ELSIF bEnabled THEN
    eState := eReady;
ELSE
    eState := eIdle;
END_IF;
stStatus.eState := eState;
stStatus.bEnabled := bEnabled;
stStatus.bBusy := bBusy;
stStatus.bDone := bDone;
stStatus.bError := bError;
stStatus.udiErrorID := udiErrorID;
stStatus.rActualPressure := INT_TO_REAL(fbReadStatus.PRESSURECONTROLLERAPPLIED);
stStatus.rActualPosition := REAL_TO_LREAL(fbReadStatus.ACTUATORPOSITION);
stStatus.rActualVelocity := REAL_TO_LREAL(fbReadStatus.ACTUATORVELOCITYCOMMAND);

IF bCycleExecuted THEN
    stStatus.bCycleReentry := TRUE;
    RETURN;
END_IF;
stStatus.bCycleReentry := FALSE;
bCycleExecuted := TRUE;
udiCycleSequence := udiCycleSequence + 1;

CASE ePolicy OF
    eMotionDefault: siStrategy := 0;
    eProcessPriority: siStrategy := 1;
ELSE
    siStrategy := 0;
END_CASE;
fbGetPumpRequest(ENABLE := bEnable, STRATEGY := siStrategy, ALLOW_NEGATIVE := bAllowNegative);
fbServoControl(StartMotor := bEnable AND NOT fbGetPumpRequest.ERROR AND NOT fbGetPumpRequest.CONFLICT, SetVelCmd := fbGetPumpRequest.PUMPSPEED, FlowRateLimit := 1000, uiMaxMotorSpeed := uiMaxMotorSpeed, EnSimulation := FALSE, SelfLearn := FALSE, UsePlanner := FALSE);
stStatus.rPumpSpeed := fbGetPumpRequest.PUMPSPEED;
stStatus.bConflict := fbGetPumpRequest.CONFLICT;
stStatus.bBusy := fbGetPumpRequest.BUSY;
stStatus.bDone := fbGetPumpRequest.DONE;
stStatus.bError := fbGetPumpRequest.ERROR;
stStatus.wErrorID := fbGetPumpRequest.ERRORID;
bCycleExecuted := FALSE;

IF bExecute THEN
    bBusy := TRUE;
    bDone := FALSE;
    CASE iStep OF
        0:   iStep := 10; (* 锁模：快速接近 *)
        10:  iStep := 20; (* 锁模：低速合模 *)
        20:  iStep := 30; (* 锁模：压力建立 *)
        30:  iStep := 100; (* 锁模完成 *)
    END_CASE;
ELSE
    bBusy := FALSE;
    bDone := (iStep = 100);
END_IF;

IF bExecute THEN
    bBusy := TRUE;
    bDone := FALSE;
    CASE iStep OF
        0:   iStep := 10; (* 开模：脱模/破闸 *)
        10:  iStep := 20; (* 开模：快速打开 *)
        20:  iStep := 100; (* 开模：末端低速定位完成 *)
    END_CASE;
ELSE
    bBusy := FALSE;
    bDone := (iStep = 100);
END_IF;

IF bExecute THEN
    bBusy := TRUE;
    bDone := FALSE;
    CASE iStep OF
        0:   iStep := 10; (* 射胶：高速段 *)
        10:  iStep := 20; (* 射胶：低速段 *)
        20:  iStep := 30; (* 射胶：速度/压力切换 *)
        30:  iStep := 100; (* 射胶：保压结束 *)
    END_CASE;
ELSE
    bBusy := FALSE;
    bDone := (iStep = 100);
END_IF;

IF bExecute THEN
    bBusy := TRUE;
    bDone := FALSE;
    CASE iStep OF
        0:   iStep := 10; (* 储料：塑化/计量 *)
        10:  iStep := 100;
    END_CASE;
ELSE
    bBusy := FALSE;
    bDone := (iStep = 100);
END_IF;

IF bExecute THEN
    bBusy := TRUE;
    bDone := FALSE;
    CASE iStep OF
        0:   iStep := 10; (* 顶针：前进 *)
        10:  fbHold(IN := TRUE, PT := T#500ms); (* 顶针：保压/停留 *)
        20:  iStep := 100; (* 顶针：返回完成 *)
        100: bDone := TRUE;
    END_CASE;
    IF fbHold.Q THEN
        fbHold(IN := FALSE);
        iStep := 20;
    END_IF;
ELSE
    fbHold(IN := FALSE);
    bBusy := FALSE;
    bDone := (iStep = 100);
END_IF;

IF bRegisterHydraulicAxis AND NOT bHydraulicRegistered AND (uiHydAxisCount < 16) THEN
    aHydAxis[uiHydAxisCount] := iHydraulicAxis;
    aHydAxisUsed[uiHydAxisCount] := TRUE;
    bHydraulicRegistered := TRUE;
    uiHydAxisCount := uiHydAxisCount + 1;
END_IF;
IF bRegisterElectricAxis AND NOT bElectricRegistered AND (uiAxisCount < 32) THEN
    aAxis[uiAxisCount] := iElectricAxis;
    aAxisUsed[uiAxisCount] := TRUE;
    bElectricRegistered := TRUE;
    uiAxisCount := uiAxisCount + 1;
END_IF;

fbClamp(bExecute := bClampExecute);
fbMoldOpen(bExecute := bMoldOpenExecute);
fbInjection(bExecute := bInjectionExecute);
fbCharge(bExecute := bChargeExecute);
fbEject(bExecute := bEjectExecute);
fbPumpManager(bEnable := bEnable, ePolicy := ePumpPolicy, bAllowNegative := bAllowNegative, uiMaxMotorSpeed := uiMaxMotorSpeed);
bInitialized := TRUE;
bBusy := fbPumpManager.stStatus.bBusy;
bError := fbPumpManager.stStatus.bError;
stPumpStatus := fbPumpManager.stStatus;
